def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n >= 100:
        return 'D'

    my_c = 0
    opp_c = 0
    op_d_after_my_c = 0
    recent_c = 0
    recent_n = 0

    w_sum = 0.0
    w_c = 0.0

    ct_w = 0.0
    cc_w = 0.0
    dt_w = 0.0
    dc_w = 0.0

    start = n - 12
    if start < 0:
        start = 0

    for i in range(n):
        my = history[i][0]
        op = history[i][1]

        if my == 'C':
            my_c += 1
            if op == 'D':
                op_d_after_my_c += 1

        if op == 'C':
            opp_c += 1

        if n > 1:
            w = 1.0 + (float(i) / float(n - 1)) * 3.0
        else:
            w = 1.0

        w_sum += w
        if op == 'C':
            w_c += w

        if i >= start:
            recent_n += 1
            if op == 'C':
                recent_c += 1

        if i < n - 1:
            no = history[i + 1][1]
            if n > 2:
                tw = 1.0 + (float(i) / float(n - 2)) * 3.0
            else:
                tw = 1.0

            if my == 'C':
                ct_w += tw
                if no == 'C':
                    cc_w += tw
            else:
                dt_w += tw
                if no == 'C':
                    dc_w += tw

    opp_rate = float(opp_c) / float(n)
    w_rate = w_c / w_sum if w_sum > 0.0 else 0.5
    recent_rate = float(recent_c) / float(recent_n) if recent_n > 0 else opp_rate

    last_my = history[-1][0]
    last_opp = history[-1][1]

    streak_d = 0
    for i in range(n - 1, -1, -1):
        if history[i][1] == 'D':
            streak_d += 1
        else:
            break

    prev_my_was_D = False
    if n >= 2 and history[-2][0] == 'D':
        prev_my_was_D = True

    if opp_rate < 0.12 and n >= 3:
        return 'D'
    if w_rate < 0.20 and recent_rate < 0.25 and n >= 6:
        return 'D'
    if my_c >= 5 and float(op_d_after_my_c) >= 0.75 * float(my_c):
        return 'D'
    if last_my == 'C' and streak_d >= 3:
        return 'D'
    if streak_d >= 4:
        return 'D'

    if ct_w > 0.0:
        qC = (cc_w + 1.0) / (ct_w + 2.0)
    else:
        qC = w_rate

    if dt_w > 0.0:
        qD = (dc_w + 0.5) / (dt_w + 2.0)
    else:
        if w_rate > 0.85:
            qD = 0.45
        elif w_rate > 0.60:
            qD = 0.30
        elif w_rate > 0.30:
            qD = 0.15
        else:
            qD = 0.05

    if qC < 0.0:
        qC = 0.0
    if qC > 1.0:
        qC = 1.0
    if qD < 0.0:
        qD = 0.0
    if qD > 1.0:
        qD = 1.0

    remaining = 100 - n
    if remaining <= 1:
        return 'D'

    # If we just tested defection and have not yet observed the response,
    # wait one round unless we are very close to the end against a very
    # cooperative opponent.
    if last_my == 'D' and last_opp == 'C' and dt_w <= 0.0:
        if remaining > 6:
            return 'C'
        if w_rate < 0.75:
            return 'C'

    # Respond to opponent defection.
    if last_my == 'C' and last_opp == 'D':
        if prev_my_was_D:
            # This likely punished our previous defection. Try to restore
            # cooperation if the opponent otherwise looks friendly.
            if w_rate > 0.40 and streak_d <= 2 and qD < 0.55:
                if rng.random() < 0.75:
                    return 'C'
        else:
            # Unprovoked or repeated recent defection: retaliate.
            if w_rate < 0.45:
                return 'D'
            if streak_d >= 2:
                return 'D'
            if rng.random() < 0.82:
                return 'D'

    # After mutual defection against a mostly cooperative punisher, try to
    # break the loop instead of getting trapped.
    if last_my == 'D' and last_opp == 'D':
        if w_rate > 0.55 and qD <= 0.45 and streak_d <= 2:
            if rng.random() < 0.75:
                return 'C'

    # If the opponent has never defected and seems forgiving, exploit them.
    # The one-round pause above prevents a bad double-test against punishers.
    if n >= 15 and opp_c == n:
        if not (last_my == 'D' and last_opp == 'C' and dt_w <= 0.0):
            return 'D'

    # Estimate probability that opponent cooperates in the current round.
    if last_my == 'C':
        p_est = qC
    else:
        p_est = qD

    last_opp_c = 1.0 if last_opp == 'C' else 0.0
    p = 0.70 * p_est + 0.30 * last_opp_c

    if last_my == 'C' and last_opp == 'D' and p > 0.45:
        p = 0.45

    if p < 0.0:
        p = 0.0
    if p > 1.0:
        p = 1.0

    # Short finite-horizon Markov estimate:
    # If we play C now, opponent's next cooperation is estimated by qC.
    # If we play D now, opponent's next cooperation is estimated by qD.
    cv = 0.0
    dv = 0.0

    for _ in range(remaining - 1):
        nv_c = 3.0 * qC + cv
        alt_c = 1.0 + 4.0 * qC + dv
        if alt_c > nv_c:
            nv_c = alt_c

        nv_d = 3.0 * qD + cv
        alt_d = 1.0 + 4.0 * qD + dv
        if alt_d > nv_d:
            nv_d = alt_d

        cv = nv_c
        dv = nv_d

    value_c = 3.0 * p + cv
    value_d = 1.0 + 4.0 * p + dv

    if value_d > value_c + 0.20:
        return 'D'
    return 'C'
